<template><div class="page"><h1>商品管理</h1><div class="filters"><el-input v-model="name" placeholder="商品名称" clearable /><el-select v-model="status" placeholder="全部状态" clearable><el-option label="可用" :value="1"/><el-option label="不可用" :value="0"/></el-select><el-button @click="search">查询</el-button><el-button type="primary" @click="openCreate">新增商品</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table v-loading="loading" :data="data.items" empty-text="暂无商品"><el-table-column prop="id" label="ID"/><el-table-column prop="name" label="名称"/><el-table-column prop="price" label="价格（分）"/><el-table-column label="状态"><template #default="{row}">{{ row.status===1?'可用':'不可用' }}</template></el-table-column><el-table-column prop="sortOrder" label="排序值"/><el-table-column prop="createTime" label="创建时间"/><el-table-column label="操作"><template #default="{row}"><el-button text @click="openEdit(row)">查看/编辑</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" layout="prev, pager, next, total" :total="data.total" @current-change="load"/><el-dialog v-model="dialog" :title="editingId?'商品详情 / 编辑':'新增商品'" width="500"><el-form label-width="100"><el-form-item label="名称"><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="价格（分）"><el-input-number v-model="form.price" :min="0" :precision="0"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="可用" :value="1"/><el-option label="不可用" :value="0"/></el-select></el-form-item><el-form-item label="排序值"><el-input-number v-model="form.sortOrder" :precision="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { apiRequest, query, type Page, type Sku } from '../api/client'
const name=ref(''),status=ref<number|undefined>(),page=ref(1),loading=ref(false),error=ref(''),saving=ref(false)
const data=ref<Page<Sku>>({items:[],page:1,pageSize:10,total:0,totalPages:0})
const dialog=ref(false),editingId=ref<number|null>(null),form=reactive({name:'',price:0,status:1,sortOrder:0})
async function load(){loading.value=true;error.value='';try{data.value=await apiRequest(`/api/v1/admin/skus?${query({name:name.value,status:status.value,page:page.value})}`)}catch(e){error.value=e instanceof Error?e.message:'查询失败'}finally{loading.value=false}}
function search(){page.value=1;void load()}
function openCreate(){editingId.value=null;Object.assign(form,{name:'',price:0,status:1,sortOrder:0});dialog.value=true}
async function openEdit(row:Sku){try{const full=await apiRequest<Sku>(`/api/v1/admin/skus/${row.id}`);editingId.value=full.id;Object.assign(form,{name:full.name,price:full.price,status:full.status,sortOrder:full.sortOrder});dialog.value=true}catch{}}
async function save(){if(!form.name.trim()||!Number.isInteger(form.price)||form.price<0||!Number.isInteger(form.sortOrder)){ElMessage.error('请填写有效的商品名称、价格和排序值');return}saving.value=true;try{await apiRequest(editingId.value?`/api/v1/admin/skus/${editingId.value}`:'/api/v1/admin/skus',{method:editingId.value?'PUT':'POST',body:JSON.stringify(form)});dialog.value=false;await load()}finally{saving.value=false}}
async function remove(row:Sku){try{await ElMessageBox.confirm(`确定删除“${row.name}”？已关联支付记录的商品不能删除。`,'删除商品',{type:'warning'})}catch{return}try{await apiRequest(`/api/v1/admin/skus/${row.id}`,{method:'DELETE'});await load()}catch{}}
onMounted(load)
</script>
